

function saveAsPdf(){
  document.body.classList.add('print-current');
  const cleanup = () => document.body.classList.remove('print-current');
  window.addEventListener('afterprint', cleanup, {once:true});
  window.print();
  setTimeout(cleanup, 1000);
}
function toggleFullscreen(){
  if(!document.fullscreenElement){
    document.documentElement.requestFullscreen?.();
  }else{
    document.exitFullscreen?.();
  }
}
function applyDarkMode(isDark){
  document.body.classList.toggle('dark-mode', !!isDark);
  scheduleCountryMapDraw();
  const btn=document.getElementById('dark-mode-toggle');
  if(btn){ btn.textContent = isDark ? '☀' : '◐'; btn.title = isDark ? 'Lys modus' : 'Mørk modus'; }
  try{ localStorage.setItem('geoDarkMode', isDark ? '1' : '0'); }catch(e){}
}
function toggleDarkMode(){
  applyDarkMode(!document.body.classList.contains('dark-mode'));
}
document.addEventListener('DOMContentLoaded', ()=>{
  try{ applyDarkMode(localStorage.getItem('geoDarkMode') === '1'); }catch(e){}
});

function toggleMenu(header){
  const submenu = header.nextElementSibling;
  const icon = header.querySelector('.menu-icon');
  const isOpen = submenu.classList.contains('open');
  document.querySelectorAll('.submenu').forEach(s => s.classList.remove('open'));
  document.querySelectorAll('.menu-header').forEach(h => {h.classList.remove('active'); const i=h.querySelector('.menu-icon'); if(i) i.textContent='▶';});
  if(!isOpen){submenu.classList.add('open'); header.classList.add('active'); if(icon) icon.textContent='▼';}
}
function showContent(id, item){
  stopOpenGuessr();
  document.body.classList.remove('quiz-fullscreen','jeopardy-fullscreen','weather-jeopardy-fullscreen','inner-jeopardy-fullscreen','outer-jeopardy-fullscreen','resource-jeopardy-fullscreen','demography-jeopardy-fullscreen','sidebar-open');
  document.querySelectorAll('.quiz-mode-content').forEach(el => el.classList.remove('active'));
  const shell0 = document.getElementById('jeopardy-shell'); if(shell0) shell0.classList.remove('playing');
  document.getElementById('welcome').style.display='none';
  document.querySelectorAll('.page-section').forEach(section => section.classList.remove('active'));
  document.querySelectorAll('.submenu-item').forEach(i => i.classList.remove('active'));
  const section = document.getElementById(id);
  if(section){section.classList.add('active');}
  if(item){item.classList.add('active');}
  window.scrollTo({top:0, behavior:'smooth'});
}
function toggleAnswer(btn){
  const box = btn.nextElementSibling;
  box.classList.toggle('open');
  btn.textContent = box.classList.contains('open') ? 'Skjul fasit' : 'Vis fasit';
}
let landSortState = {column: 1, direction: 1};
function sortLandTable(columnIndex){
  const table = document.getElementById('land-table');
  if(!table) return;
  const tbody = table.querySelector('tbody');
  const rows = Array.from(tbody.querySelectorAll('tr'));
  if(landSortState.column === columnIndex){
    landSortState.direction *= -1;
  }else{
    landSortState.column = columnIndex;
    landSortState.direction = 1;
  }
  rows.sort((a,b)=>{
    const av = a.children[columnIndex].textContent.trim().toLocaleLowerCase('nb-NO');
    const bv = b.children[columnIndex].textContent.trim().toLocaleLowerCase('nb-NO');
    return av.localeCompare(bv, 'nb-NO') * landSortState.direction;
  });
  rows.forEach(row => tbody.appendChild(row));
  table.querySelectorAll('.sort-hint').forEach(s => s.textContent='↕');
  const hint = table.querySelectorAll('th')[columnIndex].querySelector('.sort-hint');
  if(hint) hint.textContent = landSortState.direction === 1 ? '↑' : '↓';
}

