function answerMatches(input, answer){
  const n=normalizeAnswer(input),a=normalizeAnswer(answer);
  if(!n||!a)return false;
  const compact=s=>s.replace(/\s+/g,'');
  if(n===a||compact(n)===compact(a))return true;

  /* Match the answer against every known Norwegian/English country-name group.
     Compact matching also accepts omitted hyphens/apostrophes/spaces. */
  for(const [canonical,aliases] of Object.entries(COUNTRY_NAME_ALIASES)){
    const group=[canonical,...aliases].map(normalizeAnswer).filter(Boolean);
    const answerBelongs=group.some(x=>x===a||compact(x)===compact(a));
    if(!answerBelongs)continue;
    return group.some(x=>x===n||compact(x)===compact(n));
  }
  return false;
}
