const GEO_MAP_DATA = "data:image/webp;base64,";

const GEO_MAP_TOP = 75.0;
const GEO_MAP_BOTTOM = -58.8;
const GEO_PERFECT_KM = 90;
let geoGuessrState = null;
let geoGuessrClock = null;
let geoGuessrSelection = null;

function geoMercatorY(lat){
  const r = Math.max(-89.9, Math.min(89.9, lat)) * Math.PI / 180;
  return Math.log(Math.tan(Math.PI/4 + r/2));
}
function geoInverseMercatorY(v){ return (2*Math.atan(Math.exp(v)) - Math.PI/2) * 180/Math.PI; }
function geoToPercent(lat, lon){
  const top=geoMercatorY(GEO_MAP_TOP), bottom=geoMercatorY(GEO_MAP_BOTTOM);
  return {x:(lon+180)/360*100, y:(top-geoMercatorY(lat))/(top-bottom)*100};
}
function geoPercentToLatLon(xPct,yPct){
  const top=geoMercatorY(GEO_MAP_TOP), bottom=geoMercatorY(GEO_MAP_BOTTOM);
  const lon=xPct/100*360-180;
  const m=top-(yPct/100)*(top-bottom);
  return {lat:geoInverseMercatorY(m),lon};
}
function geoDistanceKm(a,b){
  const R=6371, toRad=v=>v*Math.PI/180;
  const dLat=toRad(b.lat-a.lat);
  const lonDelta=((b.lon-a.lon+540)%360)-180;
  const dLon=toRad(lonDelta);
  const la1=toRad(a.lat), la2=toRad(b.lat);
  const h=Math.sin(dLat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;
  return 2*R*Math.asin(Math.min(1,Math.sqrt(h)));
}
function geoBasePoints(km){
  if(km<=GEO_PERFECT_KM) return 100;
  return Math.max(0,100*Math.exp(-(km-GEO_PERFECT_KM)/1800));
}

function geoTimeBonus(sec){
  if(sec>=30) return 0;
  const effectiveSec=Math.max(0,sec-1);
  return 10*Math.exp(-effectiveSec/6.5);
}

function geoAdjustedTimeBonus(sec,basePoints){
  return geoTimeBonus(sec)*Math.max(0,Math.min(1,basePoints/100));
}
function geoPlayable(t){ return Number.isFinite(t.lat)&&Number.isFinite(t.lon)&&t.lat<=GEO_MAP_TOP&&t.lat>=GEO_MAP_BOTTOM; }
function geoUniqueTargets(arr){
  const seen=new Set();
  return arr.filter(t=>{ const k=(t.name+'|'+t.lat.toFixed(3)+'|'+t.lon.toFixed(3)).toLowerCase(); if(seen.has(k)) return false; seen.add(k); return true; });
}
function geoPlayableCapitals(){ return geoUniqueTargets(GEO_CAPITAL_TARGETS.filter(geoPlayable)); }
function geoPlayablePlaces(){ return geoUniqueTargets(GEO_PLACE_TARGETS.filter(geoPlayable)); }
function geoSelectionOptions(){
  const places=geoPlayablePlaces();
  const categories=[];
  for(const t of places) if(t.category && !categories.includes(t.category)) categories.push(t.category);
  return [
    {key:'capitals',label:'Hovedsteder',count:geoPlayableCapitals().length},
    ...categories.map(category=>({key:'place:'+category,label:category,count:places.filter(t=>t.category===category).length}))
  ];
}
function ensureGeoGuessrSelection(){
  const valid=new Set(geoSelectionOptions().map(o=>o.key));
  if(!(geoGuessrSelection instanceof Set)) geoGuessrSelection=new Set(valid);
  else geoGuessrSelection=new Set([...geoGuessrSelection].filter(k=>valid.has(k)));
}
function geoTargetPoolFromSelection(){
  ensureGeoGuessrSelection();
  const pool=[];
  if(geoGuessrSelection.has('capitals')) pool.push(...geoPlayableCapitals());
  for(const t of geoPlayablePlaces()) if(geoGuessrSelection.has('place:'+t.category)) pool.push(t);
  return geoUniqueTargets(pool);
}
function stopGeoGuessrClock(){ if(geoGuessrClock){ clearInterval(geoGuessrClock); geoGuessrClock=null; } }
function initGeoGuessr(){
  stopGeoGuessrClock(); geoGuessrState=null;
  const app=document.getElementById('geo-guessr-app'); if(!app) return;
  ensureGeoGuessrSelection();
  const options=geoSelectionOptions();
  const items=options.map(o=>`<label class="geo-selection-item"><input type="checkbox" data-geo-key="${escapeGeoHtml(o.key)}" ${geoGuessrSelection.has(o.key)?'checked':''} onchange="toggleGeoGuessrSelectionCheckbox(this)"><span><strong>${escapeGeoHtml(o.label)}</strong><small>${o.count} steder</small></span></label>`).join('');
  const selectedCount=geoTargetPoolFromSelection().length;
  app.innerHTML=`<div class="geo-guessr-setup-wrap"><div class="geo-guessr-setup"><h3>MapWiz</h3><p>Klikk på kjente steder på kartet. Jo nærmere du kommer desto mer poeng får du. Maks er 100 geografipoeng + 10 tidsbonus per sted.</p><p style="font-size:.9rem;margin-top:6px">Tidsbonusen faller med tiden, men <strong style="color:#fff">vektes også med treffsikkerheten</strong>. Et raskt klikk på feil side av kloden gir derfor nesten ingen bonus.</p><div class="geo-selection-tools"><button type="button" onclick="setAllGeoGuessrSelections(true)">Velg alle</button><button type="button" onclick="setAllGeoGuessrSelections(false)">Fjern alle</button><span class="geo-selection-count" id="geo-selection-count">${selectedCount} steder valgt</span></div><div class="geo-selection-grid">${items}</div><div class="geo-selection-error" id="geo-selection-error"></div><div class="geo-setup-actions"><button class="geo-start-button" id="geo-start-button" onclick="startGeoGuessr()" ${selectedCount<10?'disabled':''}>Start 10 steder</button><button class="geo-setup-back" onclick="exitQuizMode()">Tilbake til testvalg</button></div></div></div>`;
}
function refreshGeoGuessrSelectionStatus(){
  const n=geoTargetPoolFromSelection().length;
  const count=document.getElementById('geo-selection-count'); if(count) count.textContent=`${n} steder valgt`;
  const start=document.getElementById('geo-start-button');
  if(start){
    start.disabled=n<10;
    const allCurriculum=geoGuessrSelection.size===1&&geoGuessrSelection.has('place:Geografifaget1');
    start.textContent=allCurriculum?`Start alle ${n} steder`:'Start 10 steder';
  }
  const err=document.getElementById('geo-selection-error'); if(err) err.textContent=n<10?'Velg kategorier som til sammen gir minst 10 steder.':'';
}
function toggleGeoGuessrSelectionCheckbox(input){
  ensureGeoGuessrSelection();
  const key=input?.dataset?.geoKey; if(!key) return;
  if(input.checked) geoGuessrSelection.add(key); else geoGuessrSelection.delete(key);
  refreshGeoGuessrSelectionStatus();
}
function setAllGeoGuessrSelections(on){
  const options=geoSelectionOptions();
  geoGuessrSelection=on?new Set(options.map(o=>o.key)):new Set();
  document.querySelectorAll('.geo-selection-item input[type="checkbox"]').forEach(el=>el.checked=on);
  refreshGeoGuessrSelectionStatus();
}
function startGeoGuessr(){
  stopGeoGuessrClock();
  const pool=shuffleArray(geoTargetPoolFromSelection());
  if(pool.length<10){ refreshGeoGuessrSelectionStatus(); return; }
  const rounds=pool.slice(0,10);
  geoGuessrState={rounds,index:0,total:0,baseTotal:0,bonusTotal:0,results:[],answered:false,questionStarted:performance.now()};
  renderGeoGuessrRound();
}
function renderGeoGuessrRound(){
  stopGeoGuessrClock();
  const s=geoGuessrState, app=document.getElementById('geo-guessr-app'); if(!s||!app) return;
  if(s.index>=s.rounds.length) return renderGeoGuessrSummary();
  s.answered=false; s.questionStarted=performance.now();
  const t=s.rounds[s.index];
  app.innerHTML=`<div class="geo-map-stage" id="geo-map-stage" onclick="geoMapClick(event)"><img class="geo-map-image" alt="Fysisk verdenskart" src="${GEO_MAP_DATA}"><svg class="geo-line-layer" id="geo-line-layer" viewBox="0 0 100 100" preserveAspectRatio="none"></svg><div id="geo-markers"></div><button class="geo-map-exit" onclick="event.stopPropagation();initGeoGuessr()">Avslutt</button><div class="geo-hud" id="geo-hud" onclick="event.stopPropagation()"><div class="geo-hud-top"><span class="geo-hud-pill">${s.index+1} / ${s.rounds.length}</span><span class="geo-hud-pill">Poeng: ${s.total.toFixed(1)}</span><span class="geo-hud-spacer"></span><span class="geo-hud-pill" id="geo-time-pill">Mulig tidsbonus: 10.0</span></div><div class="geo-target-label">${escapeGeoHtml(t.name)}</div><div class="geo-hint" id="geo-hint">Klikk på kartet der du mener stedet ligger.</div><div class="geo-feedback" id="geo-feedback" style="display:none"></div></div></div>`;
  geoGuessrClock=setInterval(updateGeoGuessrClock,100);
}
function updateGeoGuessrClock(){
  const s=geoGuessrState; if(!s||s.answered) return stopGeoGuessrClock();
  const elapsed=(performance.now()-s.questionStarted)/1000;
  const el=document.getElementById('geo-time-pill'); if(el) el.textContent=`Mulig tidsbonus: ${geoTimeBonus(elapsed).toFixed(1)}`;
}

function geoWrappedLineSvg(x1,y1,x2,y2){
  const dx=x2-x1;
  if(Math.abs(dx)<=50){
    return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line>`;
  }

  if(dx>50){
    const x2w=x2-100;
    const t=(0-x1)/(x2w-x1);
    const yc=y1+t*(y2-y1);
    return `<line x1="${x1}" y1="${y1}" x2="0" y2="${yc}"></line>
            <line x1="100" y1="${yc}" x2="${x2}" y2="${y2}"></line>`;
  }else{
    const x2w=x2+100;
    const t=(100-x1)/(x2w-x1);
    const yc=y1+t*(y2-y1);
    return `<line x1="${x1}" y1="${y1}" x2="100" y2="${yc}"></line>
            <line x1="0" y1="${yc}" x2="${x2}" y2="${y2}"></line>`;
  }
}

function geoMapClick(ev){
  const s=geoGuessrState; if(!s||s.answered) return;
  const stage=document.getElementById('geo-map-stage'); if(!stage) return;
  const rect=stage.getBoundingClientRect();
  const xPct=(ev.clientX-rect.left)/rect.width*100, yPct=(ev.clientY-rect.top)/rect.height*100;
  if(xPct<0||xPct>100||yPct<0||yPct>100) return;
  s.answered=true; stopGeoGuessrClock();
  const guess=geoPercentToLatLon(xPct,yPct), target=s.rounds[s.index];
  const km=geoDistanceKm(guess,target), elapsed=(performance.now()-s.questionStarted)/1000;
  const base=geoBasePoints(km), rawBonus=geoTimeBonus(elapsed), bonus=geoAdjustedTimeBonus(elapsed,base), points=base+bonus;
  s.total+=points; s.baseTotal+=base; s.bonusTotal+=bonus;
  s.results.push({name:target.name,km,base,bonus,points});
  const targetPct=geoToPercent(target.lat,target.lon);
  const markers=document.getElementById('geo-markers');
  if(markers) markers.innerHTML=`<div class="geo-marker guess" style="left:${xPct}%;top:${yPct}%" title="Ditt treff"></div><div class="geo-marker answer" style="left:${targetPct.x}%;top:${targetPct.y}%" title="Riktig sted"></div>`;
  const svg=document.getElementById('geo-line-layer'); if(svg) svg.innerHTML=geoWrappedLineSvg(xPct,yPct,targetPct.x,targetPct.y);
  const description=target.kind==='Hovedstad' ? `Hovedstad i ${target.country}.` : (target.explanation || target.category || 'Kjent sted');
  const hud=document.getElementById('geo-hud'); if(hud) hud.classList.add('answered');
  const hint=document.getElementById('geo-hint'); if(hint) hint.textContent=description;
  const fb=document.getElementById('geo-feedback');
  if(fb){ fb.style.display='block'; fb.innerHTML=`<strong>${Math.round(km).toLocaleString('nb-NO')} km unna</strong> · ${base.toFixed(1)} geografi + ${bonus.toFixed(1)} tidsbonus = <strong>${points.toFixed(1)} p</strong><br><button class="geo-next-button" onclick="nextGeoGuessrRound()">${s.index+1>=s.rounds.length?'Se resultat (space)':'Neste sted (space)'}</button>`; }
  const pill=document.getElementById('geo-time-pill'); if(pill) pill.textContent=`Tidsbonus: ${bonus.toFixed(1)}`;
}
function nextGeoGuessrRound(){ if(!geoGuessrState) return; geoGuessrState.index++; renderGeoGuessrRound(); }
function renderGeoGuessrSummary(){
  stopGeoGuessrClock(); const s=geoGuessrState, app=document.getElementById('geo-guessr-app'); if(!s||!app) return;
  const rows=s.results.map(r=>`<div class="geo-summary-row"><span title="${escapeGeoHtml(r.name)}">${escapeGeoHtml(r.name)}</span><span>${Math.round(r.km).toLocaleString('nb-NO')} km</span><span>${r.points.toFixed(1)} p</span></div>`).join('');
  app.innerHTML=`<div class="geo-map-stage"><img class="geo-map-image" alt="Fysisk verdenskart" src="${GEO_MAP_DATA}"><button class="geo-map-exit" onclick="initGeoGuessr()">Avslutt</button><div class="geo-hud geo-summary-hud"><div class="geo-target-label">${s.total.toFixed(1)} / ${s.rounds.length*110} poeng</div><div class="geo-hint">Geografi: ${s.baseTotal.toFixed(1)} · tidsbonus: ${s.bonusTotal.toFixed(1)}</div><div class="geo-summary"><div class="geo-summary-header"><span>Sted</span><span>Avstand</span><span>Poeng</span></div>${rows}</div><div class="geo-summary-actions"><button class="geo-next-button" onclick="startGeoGuessr()">Spill igjen</button><button class="geo-next-button" onclick="initGeoGuessr()">Endre utvalg</button><button class="geo-next-button" onclick="exitQuizMode()">Tilbake</button></div></div></div>`;
}
function escapeGeoHtml(s){ return (s??'').toString().replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }


function startOpenGuessr(){
  const frame=document.getElementById('openguessr-frame');
  if(frame && frame.getAttribute('src') !== frame.dataset.src) frame.src=frame.dataset.src;
}
function stopOpenGuessr(){
  const frame=document.getElementById('openguessr-frame');
  if(frame && frame.getAttribute('src') !== 'about:blank') frame.src='about:blank';
}

function showQuizMode(mode, btn){
  stopWorldTrainerTimer();
  if(mode !== 'openguessr') stopOpenGuessr();
  if(['countries','capitals','flags','flagcapital','places','detective2'].includes(mode)) clearInactiveWorldApps(mode);
  document.querySelectorAll('.quiz-mode-content').forEach(el => el.classList.remove('active'));
  const map = {
    jeopardy:'quiz-jeopardy', countries:'quiz-countries', capitals:'quiz-capitals', flags:'quiz-flags',
    flagcapital:'quiz-flagcapital', places:'quiz-places', detective2:'quiz-detective2', geoguessr:'quiz-geoguessr',
    openguessr:'quiz-openguessr'
  };
  const content = document.getElementById(map[mode] || 'quiz-jeopardy');
  if(content) content.classList.add('active');
  document.querySelectorAll('.quiz-mode-card').forEach(card => card.classList.remove('active'));
  if(btn) btn.classList.add('active');
  document.body.classList.add('quiz-fullscreen');
  document.body.classList.remove('sidebar-open','jeopardy-fullscreen');
  const quizSection = document.getElementById('verden-quiz');
  if(quizSection) quizSection.classList.add('active');
  if(mode === 'jeopardy') { initJeopardyPicker(); renderTeamInputs(); }
  else if(mode === 'geoguessr') { initGeoGuessr(); }
  else if(mode === 'openguessr') { startOpenGuessr(); }
  else { initWorldTrainer(mode); }
}

function toggleQuizSidebar(){
  document.body.classList.toggle('sidebar-open');
}
function exitQuizMode(){
  stopWorldTrainerTimer();
  worldTrainerRunSeq++;
  worldTrainerState=null;
  stopGeoGuessrClock();
  stopOpenGuessr();
  document.body.classList.remove('quiz-fullscreen','sidebar-open','jeopardy-fullscreen');
  document.querySelectorAll('.quiz-mode-content').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('.quiz-mode-card').forEach(card => card.classList.remove('active'));
  returnToJeopardySetup(false);
  const quizSection = document.getElementById('verden-quiz');
  if(quizSection) quizSection.classList.add('active');
  window.scrollTo({top:0, behavior:'smooth'});
}
function exitJeopardyFullscreen(){
  document.body.classList.remove('jeopardy-fullscreen');
}
function initSidebarResizer(){
  const handle = document.getElementById('sidebar-resizer');
  const sidebar = document.querySelector('.sidebar');
  if(!handle || !sidebar || handle.dataset.ready === '1') return;
  handle.dataset.ready = '1';
  const setWidth = (w) => {
    const clamped = Math.max(240, Math.min(680, w));
    document.documentElement.style.setProperty('--sidebar-w', clamped + 'px');
  };
  const saved = localStorage.getItem('geoSidebarWidth');
  if(saved) setWidth(parseInt(saved, 10));
  handle.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    document.body.classList.add('resizing-sidebar');
    handle.setPointerCapture(e.pointerId);
  });
  handle.addEventListener('pointermove', (e) => {
    if(!document.body.classList.contains('resizing-sidebar')) return;
    setWidth(e.clientX);
  });
  handle.addEventListener('pointerup', (e) => {
    document.body.classList.remove('resizing-sidebar');
    const val = getComputedStyle(document.documentElement).getPropertyValue('--sidebar-w').trim().replace('px','');
    if(val) localStorage.setItem('geoSidebarWidth', val);
    try{ handle.releasePointerCapture(e.pointerId); }catch(err){}
  });
}

function renderTeamInputs(){
  const countEl = document.getElementById('team-count');
  const wrap = document.getElementById('team-name-wrap');
  if(!countEl || !wrap) return;
  const count = parseInt(countEl.value || '2',10);
  const oldValues = Array.from(wrap.querySelectorAll('input')).map(i => i.value);
  wrap.innerHTML = '';
  for(let i=0;i<count;i++){
    const div = document.createElement('div');
    div.className = 'setup-field';
    div.innerHTML = `<label>Lagnavn ${i+1}</label><input class="team-name" value="${oldValues[i] || (window.QuizLanguage?.translate('Lag '+(i+1)) || 'Lag '+(i+1))}">`;
    wrap.appendChild(div);
  }
}
function initJeopardyPicker(){
  const picker = document.getElementById('jeopardy-category-picker');
  if(!picker || picker.dataset.ready === '1') return;
  const ordered = [
    ...jeopardyCategories.filter(cat => cat.source !== 'Pensum'),
    ...jeopardyCategories.filter(cat => cat.source === 'Pensum')
  ];
  picker.innerHTML = ordered.map(cat => {
    const kind = cat.source === 'Pensum' ? 'pensum' : 'verden';
    return `<label class="jeopardy-option ${kind}"><input type="checkbox" value="${cat.id}" onchange="updateJeopardySelectionStatus(this)"><span>${cat.name}</span></label>`;
  }).join('');
  picker.dataset.ready = '1';
  updateJeopardySelectionStatus();
}
function selectedJeopardyCategories(){
  return Array.from(document.querySelectorAll('#jeopardy-category-picker input:checked')).map(cb => jeopardyCategories.find(c => c.id === cb.value)).filter(Boolean);
}
function updateJeopardySelectionStatus(changed){
  const selected = selectedJeopardyCategories();
  if(selected.length > 5 && changed){ changed.checked = false; return updateJeopardySelectionStatus(); }
  const status = document.getElementById('jeopardy-status');
  if(status){
    if(selected.length < 3) status.textContent = `Du har valgt ${selected.length}. Velg minst 3 og maks 5 kategorier.`;
    else if(selected.length <= 5) status.textContent = `Du har valgt ${selected.length}. Klar når du er klar.`;
  }
}
function startJeopardyGame(){
  initJeopardyPicker();
  renderTeamInputs();
  const selected = selectedJeopardyCategories();
  const status = document.getElementById('jeopardy-status');
  const board = document.getElementById('jeopardy-board');
  closeJeopardyCard();
  if(selected.length < 3 || selected.length > 5){
    if(status) status.textContent = `Du har valgt ${selected.length}. Velg mellom 3 og 5 kategorier.`;
    if(board) board.innerHTML = '';
    return;
  }
  document.body.classList.add('quiz-fullscreen');
  document.body.classList.remove('sidebar-open','jeopardy-fullscreen');
  const shell = document.getElementById('jeopardy-shell'); if(shell) shell.classList.add('playing');
  const gameStatus = document.getElementById('jeopardy-game-status'); if(gameStatus) gameStatus.textContent = selected.length + ' kategorier · ' + document.getElementById('team-count').value + ' lag';
  jeopardyTeams = Array.from(document.querySelectorAll('.team-name')).map((input, i)=>({name: input.value.trim() || (window.QuizLanguage?.translate('Lag '+(i+1)) || 'Lag '+(i+1)), score: 0}));
  activeJeopardyCategories = selected.map(cat => ({...cat, questions: makeJeopardyQuestions(cat)}));
  renderScoreboard();
  if(status) status.textContent = 'Spillet er i gang. Klikk på poengsummene for spørsmål. Nye tilfeldige spørsmål er trukket.';
  board.style.gridTemplateColumns = `repeat(${activeJeopardyCategories.length}, minmax(108px, 1fr))`;
  let cells = activeJeopardyCategories.map(cat => `<div class="jeopardy-cell jeopardy-head">${cat.name}</div>`).join('');
  for(let r=0;r<5;r++){
    cells += activeJeopardyCategories.map(cat => `<button class="jeopardy-cell jeopardy-value" onclick="openJeopardyQuestion('${cat.id}', ${r}, this)">${cat.questions[r].value}</button>`).join('');
  }
  board.innerHTML = cells;
}
function renderScoreboard(){
  const board = document.getElementById('jeopardy-scoreboard');
  if(!board) return;
  board.innerHTML = jeopardyTeams.map(t => `<div class="score-card"><strong>${t.name}</strong><span>${t.score}</span></div>`).join('');
}
function returnToJeopardySetup(clearSelections=true){
  const shell = document.getElementById('jeopardy-shell');
  if(shell) shell.classList.remove('playing');
  const board = document.getElementById('jeopardy-board');
  if(board) board.innerHTML = '';
  const scoreboard = document.getElementById('jeopardy-scoreboard');
  if(scoreboard) scoreboard.innerHTML = '';
  jeopardyTeams = [];
  activeJeopardyCategories = [];
  closeJeopardyCard();
  stopJeopardyTimer();
  if(clearSelections){
    document.querySelectorAll('#jeopardy-category-picker input').forEach(cb => cb.checked = false);
    updateJeopardySelectionStatus();
  }
}
function resetJeopardyBoard(){
  returnToJeopardySetup(true);
}
function openJeopardyQuestion(catId, index, button){
  const cat = activeJeopardyCategories.find(c => c.id === catId) || jeopardyCategories.find(c => c.id === catId);
  if(!cat) return;
  const item = cat.questions[index];
  jeopardyCurrent = {button, value:item.value};
  document.getElementById('jeopardy-meta').innerHTML = `<span>${cat.name}</span><span>${item.value} poeng</span>`;
  const questionEl = document.getElementById('jeopardy-question');
  if(item.html){ questionEl.innerHTML = item.html; }
  else { questionEl.textContent = item.q; }
  const answer = document.getElementById('jeopardy-answer');
  answer.textContent = item.a;
  answer.classList.remove('open');
  const actions = document.getElementById('score-actions');
  if(actions) actions.innerHTML = '';
  const closeBtn = document.getElementById('jeopardy-card-close');
  if(closeBtn) closeBtn.style.display = 'none';
  document.getElementById('jeopardy-card').classList.add('open');
  if(button) button.classList.add('done');
  startQuestionTimer();
}
function renderScoreActions(value){
  const wrap = document.getElementById('score-actions');
  if(!wrap) return;
  if(!jeopardyTeams.length){ wrap.innerHTML = ''; return; }
  wrap.innerHTML = jeopardyTeams.map((t,i)=>`<button class="score-button" onclick="adjustScore(${i}, ${value})">+${value} til ${t.name}</button><button class="score-button minus" onclick="adjustScore(${i}, -${value})">−${value} fra ${t.name}</button>`).join('');
}
function adjustScore(teamIndex, delta){
  if(!jeopardyTeams[teamIndex]) return;
  jeopardyTeams[teamIndex].score += delta;
  renderScoreboard();
}
function revealJeopardyAnswer(){
  const answer = document.getElementById('jeopardy-answer');
  if(answer) answer.classList.add('open');
  if(jeopardyCurrent) renderScoreActions(jeopardyCurrent.value);
  const closeBtn = document.getElementById('jeopardy-card-close');
  if(closeBtn) closeBtn.style.display = 'inline-flex';
}
function closeJeopardyCard(){
  const card = document.getElementById('jeopardy-card');
  if(card) card.classList.remove('open');
  const answer = document.getElementById('jeopardy-answer');
  if(answer) answer.classList.remove('open');
  const actions = document.getElementById('score-actions');
  if(actions) actions.innerHTML = '';
  const closeBtn = document.getElementById('jeopardy-card-close');
  if(closeBtn) closeBtn.style.display = 'none';
  stopQuestionTimer();
}
function startQuestionTimer(){
  stopQuestionTimer();
  const timerSelect = document.getElementById('jeopardy-timer');
  const pill = document.getElementById('timer-pill');
  const seconds = parseInt(timerSelect?.value || '0',10);
  if(!pill) return;
  if(!seconds){ pill.style.display = 'none'; return; }
  let remaining = seconds;
  pill.style.display = 'inline-block';
  pill.textContent = `${remaining} sek`;
  jeopardyTimerInterval = setInterval(()=>{
    remaining -= 1;
    pill.textContent = `${remaining} sek`;
    if(remaining <= 0){ stopQuestionTimer(); pill.style.display = 'inline-block'; pill.textContent = 'Tid!'; }
  },1000);
}
function stopQuestionTimer(){
  if(jeopardyTimerInterval){ clearInterval(jeopardyTimerInterval); jeopardyTimerInterval = null; }
}

function closeQuizSidebarOnOutsideClick(event){
  if(!(document.body.classList.contains('quiz-fullscreen') || document.body.classList.contains('weather-jeopardy-fullscreen') || document.body.classList.contains('inner-jeopardy-fullscreen') || document.body.classList.contains('outer-jeopardy-fullscreen') || document.body.classList.contains('resource-jeopardy-fullscreen') || document.body.classList.contains('demography-jeopardy-fullscreen')) || !document.body.classList.contains('sidebar-open')) return;
  const sidebar = document.querySelector('.sidebar');
  const resizer = document.getElementById('sidebar-resizer');
  const menuButton = event.target.closest('.quiz-menu-button');
  if(menuButton) return;
  if(sidebar && sidebar.contains(event.target)) return;
  if(resizer && resizer.contains(event.target)) return;
  document.body.classList.remove('sidebar-open');
}
document.addEventListener('pointerdown', closeQuizSidebarOnOutsideClick);

document.addEventListener('DOMContentLoaded', () => { initJeopardyPicker(); renderTeamInputs(); });


initSidebarResizer();


