const INNER_CONTROL_QUESTIONS = [
{cat:"Jordas oppbygning",q:"Hvor gammel er jorda, og hvordan dateres gamle bergarter?",a:"Jorda er omtrent 4,6 milliarder år gammel. Radiometrisk datering måler forholdet mellom radioaktive isotoper og nedbrytningsprodukter."},
{cat:"Jordas oppbygning",q:"Hva er de viktigste kildene til varme i jordas indre?",a:"Restvarme fra jordas dannelse og varme fra radioaktiv nedbrytning, særlig i mantelen og jordskorpa."},
{cat:"Jordas oppbygning",q:"Hva er forskjellen på indre og ytre kjerne?",a:"Den indre kjernen er fast på grunn av det enorme trykket. Den ytre kjernen er flytende, og bevegelsene der bidrar til magnetfeltet."},
{cat:"Jordas oppbygning",q:"Hvordan kan mantelen bevege seg når den for det meste er fast?",a:"Over svært lang tid kan varm mantelbergart deformeres og strømme sakte som et svært seigt materiale."},
{cat:"Jordas oppbygning",q:"Hva er forskjellen på jordskorpe og litosfære?",a:"Jordskorpa er jordas ytterste lag. Litosfæren består av jordskorpa og den stive øverste delen av mantelen."},
{cat:"Jordas oppbygning",q:"Hvordan skiller havbunnskorpe seg fra kontinentalskorpe?",a:"Havbunnskorpe er tynnere, tettere og hovedsakelig basaltisk. Kontinentalskorpe er tykkere, lettere og mer variert."},
{cat:"Jordas oppbygning",q:"Hva er astenosfæren, og hvorfor er den viktig?",a:"En svak og seig del av øvre mantel som kan deformeres langsomt og lar de stive litosfæreplatene bevege seg."},
{cat:"Jordas oppbygning",q:"Hva viser den geologiske tidsskalaen?",a:"Den deler jordas historie inn i tidsavsnitt basert på store geologiske og biologiske endringer i bergarter og fossiler."},
{cat:"Kontinentaldrift",q:"Hva gikk Wegeners hypotese om kontinentaldrift ut på?",a:"Alfred Wegener hevdet at kontinentene beveger seg, og at de tidligere var samlet i et større kontinent."},
{cat:"Kontinentaldrift",q:"Nevn tre observasjoner Wegener brukte som støtte.",a:"Kystlinjer som passer sammen, like fossiler, sammenhengende bergarter og fjellkjeder og spor etter gammelt klima."},
{cat:"Kontinentaldrift",q:"Hvorfor ble ikke Wegeners forklaring godtatt med en gang?",a:"Han manglet en troverdig mekanisme som kunne forklare hvordan kontinentene beveget seg."},
{cat:"Kontinentaldrift",q:"Hva var Pangea?",a:"Et superkontinent som samlet nesten alle landområdene før oppsplittingen startet for omtrent 200 millioner år siden."},
{cat:"Kontinentaldrift",q:"Hvordan støtter alderen på havbunnen teorien om havbunnsspredning?",a:"Havbunnen er yngst ved midthavsryggen og blir gradvis eldre utover på begge sider."},
{cat:"Kontinentaldrift",q:"Hvordan støtter magnetiske striper på havbunnen havbunnsspredning?",a:"Symmetriske magnetstriper viser at basalt har størknet ved ryggen og blitt ført utover på begge sider."},
{cat:"Kontinentaldrift",q:"Hva er platetektonikk?",a:"Teorien om at litosfæren er delt i plater som beveger seg, og at samspillet mellom dem forklarer geologiske prosesser."},
{cat:"Kontinentaldrift",q:"Hvor raskt beveger litosfæreplatene seg vanligvis?",a:"Vanligvis noen få centimeter i året."},
{cat:"Platedrift",q:"Hvilke krefter bidrar til å bevege platene?",a:"Konveksjon og annen langsom bevegelse i mantelen, platedrag fra synkende havbunnsplater og ryggskyv fra midthavsrygger virker sammen."},
{cat:"Platedrift",q:"Hva er slab pull, eller platedrag?",a:"En kald og tett havbunnsplate synker i en subduksjonssone og trekker resten av platen etter seg."},
{cat:"Platedrift",q:"Hva er ridge push, eller ryggskyv?",a:"Platen glir ved hjelp av tyngdekraften ned og bort fra en høytliggende midthavsrygg."},
{cat:"Platedrift",q:"Hva skjer ved en divergerende plategrense i havet?",a:"Platene beveger seg fra hverandre, magma stiger og størkner, og ny havbunn dannes langs en midthavsrygg."},
{cat:"Platedrift",q:"Hvilken type plategrense er Den midtatlantiske ryggen, og hvilken prosess foregår der?",a:"Den midtatlantiske ryggen er en divergerende plategrense. Den skiller den nordamerikanske platen fra den eurasiske i nord og den søramerikanske platen fra den afrikanske i sør. Magma stiger og størkner, slik at havbunnsspredning danner ny havbunn."},
{cat:"Platedrift",q:"Hvorfor er vulkanismen på Island spesielt omfattende?",a:"Island ligger over Den midtatlantiske ryggen, der den nordamerikanske og den eurasiske platen beveger seg fra hverandre. Samtidig ligger øya over et hotspot med ekstra stor tilførsel av varmt mantelmateriale. Spredningssonen og hotspotet virker sammen og gir stor magmatilførsel, vulkanisme og jordskjelv."},
{cat:"Platedrift",q:"Hvordan kan en riftsone utvikle seg til et nytt hav?",a:"Vedvarende strekk gjør skorpen tynnere og mer oppsprukket. Når kontinentet deles, kan ny havbunn dannes."},
{cat:"Platedrift",q:"Hva skjer ved en transform plategrense?",a:"Platene glir sidelengs forbi hverandre. Friksjon kan låse dem, slik at spenning bygges opp og utløses som jordskjelv."},
{cat:"Platedrift",q:"Hvilken type plategrense følger San Andreas-forkastningen, og hvilken naturfare er viktigst der?",a:"San Andreas-forkastningen er en transform plategrense mellom Stillehavsplaten og den nordamerikanske platen. Platene glir sidelengs, og den viktigste naturfaren er jordskjelv."},
{cat:"Platedrift",q:"Hva skjer når en havbunnsplate møter en kontinentalplate?",a:"Havbunnsplaten subduseres. Det dannes dyphavsgrop, jordskjelv, magma og ofte en vulkansk fjellkjede."},
{cat:"Platedrift",q:"Hvorfor dannes magma over en subduksjonssone?",a:"Vann og andre flyktige stoffer fra platen som synker, senker smeltepunktet i mantelen over den."},
{cat:"Platedrift",q:"Hva skjer når to havbunnsplater kolliderer?",a:"Den ene subduseres, og det kan dannes en dyphavsgrop og en bue av vulkanske øyer."},
{cat:"Platedrift",q:"Hvilken type plategrense har dannet Marianergropa, og hva skjer med platene der?",a:"Marianergropa ligger ved en konvergerende hav–hav-plategrense, der Stillehavsplaten synker under Marianaplaten. Subduksjonen har dannet en svært dyp dyphavsgrop og en vulkansk øybue."},
{cat:"Platedrift",q:"Hvilke typer plategrenser finnes rundt Japan, og hvilke landformer og farer skaper de?",a:"Japan ligger ved flere konvergerende plategrenser der blant annet Stillehavsplaten og den filippinske havplaten subduseres. Det gir dyphavsgroper, en vulkansk øybue med blant annet Mount Fuji, sterke jordskjelv og tsunamier."},
{cat:"Platedrift",q:"Hva skjer når to kontinenter kolliderer?",a:"Skorpa presses sammen, foldes og skyves over hverandre. Den blir tykkere og heves til en fjellkjede."},
{cat:"Platedrift",q:"Hvilken type plategrense har dannet Himalaya, og hvorfor er vulkanisme mindre framtredende der enn i Andes?",a:"Himalaya er dannet ved kontinent–kontinent-kollisjon mellom den indiske og den eurasiske platen. Fjellkjedefolding bygger blant annet Mount Everest. Ingen tett havbunnsplate subduseres, så det dannes ikke den samme vulkanske buen som i Andes."},
{cat:"Platedrift",q:"Hvilken type plategrense har dannet Andes, og hvilke landformer og prosesser følger av den?",a:"Andes ligger ved hav–kontinent-subduksjon: Nazcaplaten synker under den søramerikanske platen. Det gir dyphavsgrop, jordskjelv, magma, stratovulkaner og fjellkjeden der blant annet Aconcagua ligger."},
{cat:"Platedrift",q:"Hvor ligger Mount Everest og Aconcagua, og hvilke typer plategrenser har dannet fjellområdene rundt dem?",a:"Mount Everest ligger i Himalaya, som er dannet ved kontinent–kontinent-kollisjon. Aconcagua ligger i Andes, som er dannet ved hav–kontinent-subduksjon av Nazcaplaten under Sør-Amerika."},
{cat:"Jordskjelv",q:"Hvordan oppstår et jordskjelv?",a:"Spenning bygges opp. Når friksjonen overvinnes, skjer et brått brudd og energi sendes ut som seismiske bølger."},
{cat:"Jordskjelv",q:"Hva er forskjellen på fokus og episenter?",a:"Fokus er stedet i dypet der bruddet starter. Episenteret er punktet på overflaten rett over."},
{cat:"Jordskjelv",q:"Hva er seismiske bølger?",a:"Energibølger som brer seg gjennom jorda og langs overflaten fra jordskjelvets fokus."},
{cat:"Jordskjelv",q:"Hva måler momentmagnitude?",a:"Energien som frigjøres i jordskjelvet, beregnet fra bruddflatens størrelse, forskyvning og bergartenes stivhet."},
{cat:"Jordskjelv",q:"Hvorfor er en økning på én magnitude stor?",a:"Skalaen er logaritmisk. Ett trinn gir omtrent ti ganger større bølgeutslag og rundt 32 ganger mer energi."},
{cat:"Jordskjelv",q:"Hvorfor kan to like sterke jordskjelv gi ulikt skadeomfang?",a:"Dybde, avstand, grunnforhold, byggekvalitet, befolkningstetthet, økonomi og beredskap varierer."},
{cat:"Jordskjelv",q:"Hva er etterskjelv?",a:"Mindre skjelv etter hovedskjelvet mens berggrunnen justerer seg til den nye spenningssituasjonen."},
{cat:"Jordskjelv",q:"Hvordan kan beredskap redusere jordskjelvrisiko?",a:"Gjennom byggeregler, sikring av infrastruktur, faresonekart, øvelser, informasjon og rask redning."},
{cat:"Tsunami",q:"Hvordan oppstår en tsunami?",a:"En stor vannmasse forskyves plutselig, vanligvis når havbunnen heves eller senkes i et undersjøisk jordskjelv."},
{cat:"Tsunami",q:"Hvorfor er tsunamibølger lave på dypt vann?",a:"De har svært lang bølgelengde og liten bølgehøyde ute på dypt hav, selv om de beveger seg raskt."},
{cat:"Tsunami",q:"Hvorfor vokser en tsunami nær kysten?",a:"Bølgen bremses i grunt vann, bølgelengden blir kortere og vannet stues opp i større høyde."},
{cat:"Tsunami",q:"Hvorfor lager ikke alle undersjøiske jordskjelv tsunami?",a:"Det må vanligvis skje en stor og rask vertikal forskyvning av havbunnen. Sidelengs bevegelse flytter ofte for lite vann."},
{cat:"Tsunami",q:"Hvordan kan et varslingssystem oppdage en tsunami?",a:"Seismometre registrerer skjelvet, mens bøyer og trykksensorer registrerer endringer i havet."},
{cat:"Tsunami",q:"Hva skjedde ved Fukushima i 2011?",a:"Tsunamien slo ut strøm og kjøling ved atomkraftverket og førte til en alvorlig ulykke."},
{cat:"Vulkanisme",q:"Hva er forskjellen på magma og lava?",a:"Magma er smeltet bergart under jordoverflaten og kan bestå av en flytende smelte, krystaller og oppløste gasser som vanndamp og karbondioksid. Lava er magma som har nådd overflaten; mye av gassen kan da ha sluppet ut, men lava kan fortsatt inneholde krystaller og gassbobler."},
{cat:"Vulkanisme",q:"Sammenlikn skjoldvulkaner og stratovulkaner. Hvor forekommer de vanligvis?",a:"Skjoldvulkaner er brede og slake og bygges av tyntflytende basaltlava. De er vanlige ved hotspots og spredningssoner. Stratovulkaner er bratte og lagdelte og kan ha eksplosive utbrudd; de er særlig vanlige over subduksjonssoner."},
{cat:"Vulkanisme",q:"Hvorfor er basaltisk magma ofte mindre eksplosiv?",a:"Den er vanligvis varmere og mer tyntflytende, slik at gasser lettere slipper ut."},
{cat:"Vulkanisme",q:"Hva kjennetegner en skjoldvulkan?",a:"Den er bred med slake sider og bygges oftest av mange strømmer med tyntflytende basaltlava. Skjoldvulkaner er særlig vanlige ved hotspots, som Hawaii, og ved spredningssoner."},
{cat:"Vulkanisme",q:"Hva kjennetegner en stratovulkan?",a:"Den er bratt og lagdelt. Seig og gassrik magma kan gi eksplosive utbrudd. Stratovulkaner er særlig vanlige over subduksjonssoner, som i Japan, Indonesia og Italia."},
{cat:"Vulkanisme",q:"Hvordan er Hawaii dannet selv om øygruppen ligger langt fra en plategrense, og hva viser aldersrekkefølgen på øyene?",a:"Hawaii er dannet av skjoldvulkaner over et hotspot inne på Stillehavsplaten. Øyene blir eldre bort fra det aktive hotspotet og viser retningen platen har beveget seg."},
{cat:"Vulkanisme",q:"Hvorfor har Indonesia så mange vulkaner og jordskjelv?",a:"Indonesia ligger i Ildringen / Ring of Fire ved flere konvergerende plategrenser. Subduksjon av den indo-australske platen under Sunda-delen av den eurasiske platen danner magma, stratovulkaner, jordskjelv og tsunamifare."},
{cat:"Vulkanisme",q:"Hvordan henger plategrensene mellom Afrika og Eurasia sammen med vulkanismen i Italia?",a:"Italia ligger i en komplisert konvergerende sone mellom den afrikanske og den eurasiske platen. Subduksjon og kollisjon har bidratt til vulkanisme og stratovulkaner som Vesuv; årsakene til vulkanismen ved Etna er mer sammensatte."},
{cat:"Vulkanisme",q:"Hva har Mount Fuji og Vesuv til felles, og hvordan henger plasseringen deres sammen med vulkantypen?",a:"Mount Fuji i Japan og Vesuv i Italia er aktive stratovulkaner i områder preget av konvergerende plategrenser og subduksjon. Slike soner kan danne seig og gassrik magma, og vulkanene kan derfor få eksplosive utbrudd."},
{cat:"Vulkanisme",q:"Hva er et krater, og hvor på en vulkan finner vi det vanligvis?",a:"Et krater er den skålformede åpningen eller forsenkningen rundt et vulkansk utbruddssted. Det ligger vanligvis på toppen av vulkanen, men kratere kan også finnes langs sprekker eller på vulkanens sider."},
{cat:"Vulkanisme",q:"Hva er en pyroklastisk strøm?",a:"En rask, tett og svært varm strøm av gass, aske og steinfragmenter nedover en vulkan."},
{cat:"Vulkanisme",q:"Hva er en lahar?",a:"En rask strøm av vann, aske og vulkanske løsmasser."},
{cat:"Vulkanisme",q:"Hvordan dannes en vulkankjede over et hotspot?",a:"Platen beveger seg over et forholdsvis stasjonært varmt område, slik at nye vulkaner dannes etter tur."},
{cat:"Vulkanisme",q:"Hvordan kan store vulkanutbrudd påvirke klimaet?",a:"Svovelholdige partikler i stratosfæren kan reflektere sollys og gi midlertidig global avkjøling."},
{cat:"Vulkanisme",q:"Hva var Toba-utbruddet, og hva er forskerne sikre og usikre på om følgene?",a:"Toba var et svært stort utbrudd i Indonesia for omtrent 74 000 år siden. Det kan ha gitt midlertidig global avkjøling, men hvor store følger det fikk for menneskene, er omdiskutert."},
{cat:"Vulkanisme",q:"Hvilke ressurser kan vulkanisme gi?",a:"Fruktbar jord, geotermisk energi, mineraler, byggematerialer og turisme."},
{cat:"Bergarter og Norge",q:"Hva er et mineral?",a:"Et naturlig, fast stoff med bestemt kjemisk sammensetning og krystallstruktur."},
{cat:"Bergarter og Norge",q:"Hvordan dannes magmatiske bergarter?",a:"En magmatisk bergart dannes når magma eller lava avkjøles og størkner."},
{cat:"Bergarter og Norge",q:"Hva er forskjellen på dagbergarter og dypbergarter?",a:"Dagbergarter størkner raskt på eller nær overflaten. Dypbergarter størkner langsomt i dypet."},
{cat:"Bergarter og Norge",q:"Hvordan dannes sedimentære bergarter?",a:"En sedimentær bergart dannes når sedimenter avsettes, begraves, presses sammen og sementeres, eller ved kjemisk eller organisk utfelling."},
{cat:"Bergarter og Norge",q:"Hvordan dannes metamorfe bergarter?",a:"En metamorf bergart dannes når en eldre bergart omdannes av høyt trykk og temperatur uten å smelte."},
{cat:"Bergarter og Norge",q:"Hvordan kan gneis dannes, og hvordan kjenner vi ofte igjen bergarten?",a:"Gneis er en metamorf bergart som dannes når en eldre bergart omdannes ved høyt trykk og temperatur. Den har ofte tydelige lyse og mørke bånd."},
{cat:"Bergarter og Norge",q:"Forklar bergartenes kretsløp.",a:"Bergarter kan forvitre, avsettes, begraves, omdannes, smelte og størkne på nytt, slik at én type blir til en annen."},
{cat:"Bergarter og Norge",q:"Hvordan ble den kaledonske fjellkjeden dannet?",a:"Laurentia og Baltika kolliderte. Bergarter ble foldet, og store flak ble skjøvet over hverandre."},
{cat:"Bergarter og Norge",q:"Hvordan påvirket åpningen av Nord-Atlanteren norsk geologi?",a:"Norge og Grønland ble trukket fra hverandre. Strekk, forkastninger og innsynking dannet bassenger på sokkelen."},
{cat:"Bergarter og Norge",q:"Hva er kontinentalsokkelen?",a:"Den relativt grunne, undersjøiske fortsettelsen av et kontinent fram til sokkelkanten."},
{cat:"Bergarter og Norge",q:"Hvordan henger fjellkjededanning sammen med sedimenter på norsk sokkel?",a:"Erosjon av gamle fjell ga løsmasser som ble fraktet og avsatt i bassenger utenfor kysten."},
{cat:"Bergarter og Norge",q:"Hvorfor brukes seismiske undersøkelser på norsk sokkel?",a:"Lydbølger gir bilder av lag og forkastninger og brukes til å tolke geologisk historie, ressurser og farer."},
{cat:"Bergarter og Norge",q:"Hvordan kan indre krefter både skape farer og ressurser?",a:"De kan gi jordskjelv, tsunamier og vulkanutbrudd, men også mineraler, geotermisk energi, fruktbar jord og olje- og gassfeller."}
];

